#include "pvdg_ui_restart_prompt.h"
#include <string.h>
#include "pvdg_ui_theme.h"
typedef struct{lv_obj_t*root,*summary,*msg,*restart,*refresh;pvdg_ui_restart_prompt_callbacks_t cb;bool busy;}ui_t;static ui_t s;static void hide(lv_event_t*e){(void)e;pvdg_ui_restart_prompt_hide();}static void restart(lv_event_t*e){(void)e;if(!s.busy&&s.cb.request_restart)s.cb.request_restart(s.cb.user);}static void refresh(lv_event_t*e){(void)e;if(!s.busy&&s.cb.request_refresh)s.cb.request_refresh(s.cb.user);}static lv_obj_t*button(lv_obj_t*p,const char*t,lv_event_cb_t cb){lv_obj_t*b=lv_button_create(p);lv_obj_t*l=pvdg_ui_make_muted(b,t);lv_obj_center(l);lv_obj_add_event_cb(b,cb,LV_EVENT_CLICKED,NULL);return b;}
lv_obj_t*pvdg_ui_restart_prompt_create(const pvdg_ui_restart_prompt_callbacks_t*cb){memset(&s,0,sizeof(s));if(cb)s.cb=*cb;s.root=lv_obj_create(lv_layer_top());lv_obj_set_size(s.root,LV_PCT(100),LV_PCT(100));lv_obj_set_style_bg_opa(s.root,LV_OPA_90,LV_PART_MAIN);lv_obj_t*c=pvdg_ui_make_card(s.root);lv_obj_set_size(c,600,250);lv_obj_align(c,LV_ALIGN_CENTER,0,0);lv_obj_set_layout(c,LV_LAYOUT_FLEX);lv_obj_set_flex_flow(c,LV_FLEX_FLOW_COLUMN);pvdg_ui_make_title(c,"Controller Restart Required");s.summary=pvdg_ui_make_muted(c,"Saved configuration requires restart.");s.msg=pvdg_ui_make_muted(c,"Automatic control may already be disabled.");lv_obj_t*a=lv_obj_create(c);pvdg_ui_style_root(a);lv_obj_set_width(a,LV_PCT(100));lv_obj_set_height(a,52);lv_obj_set_layout(a,LV_LAYOUT_FLEX);lv_obj_set_flex_flow(a,LV_FLEX_FLOW_ROW);s.restart=button(a,"Restart Controller",restart);s.refresh=button(a,"Refresh Status",refresh);button(a,"Later",hide);lv_obj_add_flag(s.root,LV_OBJ_FLAG_HIDDEN);return s.root;}void pvdg_ui_restart_prompt_show(const char*x){if(!s.root)return;pvdg_ui_label_set_if_changed(s.summary,x&&x[0]?x:"Saved configuration requires restart.");lv_obj_remove_flag(s.root,LV_OBJ_FLAG_HIDDEN);lv_obj_move_foreground(s.root);}void pvdg_ui_restart_prompt_hide(void){if(s.root)lv_obj_add_flag(s.root,LV_OBJ_FLAG_HIDDEN);}void pvdg_ui_restart_prompt_apply_state(const pvdg_ui_restart_prompt_state_t*st){s.busy=st&&st->busy;if(st&&st->message)pvdg_ui_label_set_if_changed(s.msg,st->message);if(s.busy){lv_obj_add_state(s.restart,LV_STATE_DISABLED);lv_obj_add_state(s.refresh,LV_STATE_DISABLED);}else{lv_obj_remove_state(s.restart,LV_STATE_DISABLED);lv_obj_remove_state(s.refresh,LV_STATE_DISABLED);}}
